        if add {
            self.open_tabs = toggle_open(&self.open_tabs, tab);
        } else {
            self.open_tabs = vec![tab];
            if clicks >= 2 && !self.collapsed {
                self.toggle_collapsed(cx);
            }
        }
        cx.notify();
    }

